ACT.chemNew = () => openModal({ title: 'Add chemical to register', size: 'wide', body: `<div class="form-grid">${fld({ name: 'name', label: 'Product name', required: true })}${fld({ name: 'supplier', label: 'Supplier', required: true })}${fld({ name: 'site', label: 'Site', type: 'select', options: siteOptions(defaultSite(), false), required: true })}${fld({ name: 'location', label: 'Storage location', required: true })}${fld({ name: 'qty', label: 'Quantity' })}${fld({ name: 'hazard', label: 'Hazard classification (from SDS)', required: true })}${fld({ name: 'handling', label: 'Handling controls', type: 'textarea', full: true })}${fld({ name: 'emergency', label: 'Emergency response', type: 'textarea', full: true })}</div><p class="muted mt-s">Upload the SDS from the chemical record after saving.</p>`,
  buttons: [{ label: 'Add chemical', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m), id = nextId('CH-', 'chemicals'); S.chemicals.push(Object.assign({ id, org: siteOrgOf(v.site), sds: null, sdsDate: null, sdsReviewDue: TODAY, ppe: [], risks: [], course: 'CRS-HCA' }, v)); log(`Added chemical ${v.name}`, '#/chemicals/' + id); save(); toast('Chemical added — SDS required.'); navigate('#/chemicals/' + id); } }] });

